-- Paket ABT w2a-kebendaan (agen W2a, 21 Okt 2026): variabel 4780-4849 untuk harta bersama, kewarisan, wasiat, hibah, wakaf dan ekonomi syariah (blangko derry_briantono).
-- Dijalankan: mysql --default-character-set=latin1 aps_badilag < abt-w2a-PASANG.sql
-- Isi teks berupa literal heksadesimal (bita ASCII apa adanya). JANGAN disunting di editor.

SET NAMES latin1;
-- PRASYARAT: berhenti dengan galat "Subquery returns more than 1 row" bila jatah 4780-4849 sudah terpakai atau variabel lama yang dirujuk tidak lengkap. Tidak ada yang ditulis.
SELECT IF((SELECT COUNT(*) FROM abt_variabel WHERE no_var BETWEEN 4780 AND 4849) = 0 AND (SELECT COUNT(*) FROM abt_variabel WHERE no_var IN (46, 47, 53, 218, 1025, 1246, 1509, 2026, 7037, 8554)) = 10, 'PRASYARAT COCOK - memasang', (SELECT 'PRASYARAT GAGAL' UNION SELECT 'BERHENTI')) AS prasyarat;

START TRANSACTION;
